"""EvidenceAgent: generated by G2C for E2A v1.2; completed by hand.

Reads the facts from the systems of record through io_read only (replay-safe; the governance
tool_policy limits it to the five read tools), starting from the identifiers in the request and
following the links between the systems: a bank line's candidate settlements, an order's
settlement, a settlement's events and audit findings. Each fact becomes an evidence item with an
identifier (services/evidence.py). A system that does not answer is recorded as a gap, never
guessed. No model step."""
import logging
from decimal import Decimal

from e2a import BaseAgent

from ..services import documents
from ..services.evidence import item, money

MAX_SETTLEMENTS = 3


class EvidenceAgent(BaseAgent):
    agent_name = 'EvidenceAgent'

    def _prepare(self, state, ctx, io_read):
        """Read the facts this agent needs (replay-safe reads; no side effects)."""
        evidence, gaps, settlements = [], [], []
        if state.get('intent') == 'POLICY':      # a question about the rules: the customer's own documents
            evidence += documents.store().search(state.get('tenant_id') or '', str(state.get('query', '')))
            if not evidence:
                gaps.append('no document of this customer answers the question')
        if state.get('line_id'):
            result = io_read.call('get_reconciliation_exception', {'params': {}})
            if not result.get('physical_success'):
                gaps.append('reconciliation-service did not answer')
            else:
                case = next((c for c in result.get('body') or [] if c.get('line_id') == state['line_id']), None)
                if case is None:
                    gaps.append(f"no reconciliation exception for bank line {state['line_id']}")
                else:
                    evidence.append(item('recon', case['line_id'], self._case_text(case), case))
                    line = io_read.call('get_bank_line', {'line_id': case['line_id']})
                    if line.get('physical_success') and line.get('body'):
                        evidence.append(item('line', case['line_id'], self._line_text(line['body'], case),
                                             line['body']))
                    else:
                        gaps.append(f"bank line {case['line_id']} could not be read")
                    settlements += [c['settlement_id'] for c in case.get('candidates') or []]
                    proposal = case.get('proposal') or {}
                    settlements += list(proposal.get('settlement_ids') or [])
        if state.get('order_id'):
            result = io_read.call('get_order', {'order_id': state['order_id']})
            order = (result.get('body') or {}) if result.get('physical_success') else None
            if not order:
                gaps.append(f"order {state['order_id']} was not found or o2c-agent-service did not answer")
            else:
                evidence.append(item('order', order['order_id'], self._order_text(order), order))
                if order.get('settlement_id'):
                    settlements.append(order['settlement_id'])
        if state.get('settlement_id'):
            settlements.insert(0, state['settlement_id'])
        seen = []
        for sid in settlements:
            if sid and sid not in seen and len(seen) < MAX_SETTLEMENTS:
                seen.append(sid)
        events = None
        for sid in seen:
            result = io_read.call('get_settlement', {'settlement_id': sid})
            if not result.get('physical_success'):
                gaps.append(f'settlement {sid} was not found or settlement-service did not answer')
                continue
            s = result['body']
            evidence.append(item('settlement', sid, self._settlement_text(s), s))
            if events is None:
                feed = io_read.call('get_settlement_events', {'params': {'afterSequence': 0, 'limit': 500}})
                events = [e['event'] for e in (feed.get('body') or {}).get('events', [])] \
                    if feed.get('physical_success') else []
                if not feed.get('physical_success'):
                    gaps.append('the settlement event feed did not answer')
            for e in [e for e in events if (e.get('settlement') or {}).get('settlement_id') == sid]:
                evidence.append(item('event', e['event_id'], f"{e['event_type']} at {e.get('occurred_at')} for "
                                     f"settlement {sid}", e))
            audit = io_read.call('get_audit_findings', {'settlement_id': sid})
            if not audit.get('physical_success'):
                gaps.append(f'audit-ai-service did not answer for settlement {sid}')
            for f in audit.get('body') or []:
                evidence.append(item('audit', f['event_id'], self._finding_text(f), f))
        state['evidence'], state['evidence_gaps'] = evidence, gaps
        state['settlements'] = {e['data']['settlementId']: e['data'] for e in evidence
                                if e['source'] == 'settlement' and e['data'].get('settlementId')}

    @staticmethod
    def _case_text(c):
        text = f"Bank line {c['line_id']} is {c['kind']} ({c.get('status', 'OPEN')}): {c.get('detail')}"
        if c.get('candidates'):
            text += '; candidate settlements ' + ', '.join(
                f"{o['settlement_id']} ({money(o['amount'])} {o['currency']})" for o in c['candidates'])
        if c.get('proposal'):
            p = c['proposal']
            text += f"; reconciliation proposes {p.get('action')}" + (f": {p['rationale']}" if p.get('rationale') else '')
        return text

    @staticmethod
    def _line_text(line, case):
        """What was paid, and the difference to the nearest open item (arithmetic on the two records)."""
        text = (f"Bank statement line {line['line_id']}: {money(line['amount'])} {line['currency']} from "
                f"{line.get('counterparty_account')}, status {line.get('status')}"
                + (f", reference \"{line['reference']}\"" if line.get('reference') else ', no reference'))
        candidates = case.get('candidates') or []
        if candidates:
            sid, due = candidates[0]['settlement_id'], Decimal(str(candidates[0]['amount']))
            diff = due - Decimal(str(line['amount']))
            if diff:
                text += (f"; against settlement {sid} ({due:.2f} {candidates[0]['currency']}) the line is "
                         f"{'short' if diff > 0 else 'over'} by {abs(diff):.2f} {line['currency']}")
        return text

    @staticmethod
    def _order_text(o):
        return (f"Order {o['order_id']} is {o['status']}: {o['quantity']} x {o['sku']} for {o['customer_id']}, "
                f"{money(o['amount'])} {o['currency']}" + (f", settlement {o['settlement_id']}" if o.get('settlement_id') else '')
                + (f", reason: {o['reason']}" if o.get('reason') else ''))

    @staticmethod
    def _settlement_text(s):
        return (f"Settlement {s['settlementId']} is {s['status']}: {money(s['amount'])} {s['currency']} from "
                f"{s['payerAccount']} to {s['payeeAccount']}" + (f", reason: {s['reason']}" if s.get('reason') else ''))

    @staticmethod
    def _finding_text(f):
        hits = ', '.join(h.get('rule', '') for h in f.get('rule_hits') or []) or 'no rule hits'
        return (f"Audit finding for event {f['event_id']} ({f['event_type']}): {f['verdict']}, risk "
                f"{f['risk_band']}; {hits}" + (f"; {f['explanation']}" if f.get('explanation') else ''))

    def _build_messages(self, state, ctx):
        return None                      # deterministic: no model step

    def _handle_error(self, error, state, ctx):
        logging.error(f'[EvidenceAgent] {error}')
        state.setdefault('errors', []).append(str(error))
